WITH flattened_attrs AS (SELECT id, currency, tier_limits, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, ELEMENT_AT(tier_prices, 1) AS entry_price, SLICE(tier_limits, 1, 2) AS first_two_limits FROM price_tiers) SELECT CASE WHEN entry_price >= 27 THEN 'HIGH' ELSE 'LOW' END AS entry_price_tier, SUM(entry_price) AS total_entry_price, COUNT(*) AS row_count, COUNT(*) AS cnt, COUNT_IF(currency = 'EUR') AS eur_events FROM flattened_attrs GROUP BY CASE WHEN entry_price >= 27 THEN 'HIGH' ELSE 'LOW' END ORDER BY total_entry_price DESC NULLS LAST;
